import{z as s,x as i,o as e,c as l,q as t,j as B,D as E,d as n,s as o,S as A}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"复现包的标准","description":"","frontmatter":{"title":"复现包的标准","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/rc2-repro-package-standard.md","filePath":"quant/rc2-repro-package-standard.md","lastUpdated":1791413859000}'),d={name:"quant/rc2-repro-package-standard.md"};function p(C,a,D,m,h,f){const r=i("Mermaid");return e(),l("div",null,[a[2]||(a[2]=t('<h1 id="复现包的标准" tabindex="-1">复现包的标准 <a class="header-anchor" href="#复现包的标准" aria-label="Permalink to &quot;复现包的标准&quot;">​</a></h1><div class="epigraph"><p>复现包的验收不是「在我机器上能跑」，是「在陌生人的机器上跑出同一张表」；前一句是安装问题，后一句才是复现。</p><footer>—— 据 Sandve et al., Ten Simple Rules for Reproducible Computational Research, PLoS Computational Biology, 2013；站内研究复盘的快照双冻结口径整理</footer></div><p><a href="/quant/rc2-experiment-management">上一课</a>把一串实验收进台账，引用的靶标落在不可变存储上。缺口是交付：研究定案后要交到陌生环境里的陌生人手里——评审要看，审计要查，接手的人要跑。本课定复现包的标准：数据快照、代码、环境、入口、基准五件齐，盲跑通过才算数。它是<a href="/quant/research-postmortem">研究复盘</a>「可复现快照」一件的工程化。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>「能跑」与「跑得同」是两件事。环境锁与容器解决依赖可安装，但装好了不等于输入同一：指向「数据库当前状态」的连接，在数据修正发布后跑出的就是另一份数据——<a href="/quant/de-data-versioning">数据版本化</a>的三种不可复现（就地更新、选择性重拉、规则漂移）全部静默。输入同一了，还有输出同一：浮点归约顺序、BLAS 线程数、并行度，都会让「同一实验」的年化收益在小数点后几位开始分叉。三关全过，复现才成立；缺任何一关，复现退化为「能运行」，而能运行的假复现比明确标注「不可复现」更危险——它让人以为核查过了。</p><p><span class="marginnote">数字实例看浮点分叉：对一百万个浮点数求和，串行从左加到右、并行按线程分块再加总，加法顺序不同，结果可差在小数点后第六位；传导到年化收益就是小数点后第四位的分叉。这不是 bug，是浮点运算的物理性质——所以基准 diff 必须预先声明「差在第几位以内算过」，而不是让每个复现者自己猜。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><h3 id="五件套" tabindex="-1">五件套 <a class="header-anchor" href="#五件套" aria-label="Permalink to &quot;五件套&quot;">​</a></h3><p><strong>数据快照引用</strong>：钉快照 ID，不钉地址；快照不可变是<a href="/quant/de-data-versioning">数据版本化</a>的旧版本永不变原则。<strong>代码 tag</strong>：定案时刻打 tag，此后任何改动都是新版本。<strong>环境锁</strong>：依赖清单钉版本，附硬件与线程数说明。<strong>单命令入口</strong>：从快照到结果表一条命令，无手动步骤——Sandve 第二条「避免手动数据操作」：每一步手工操作都是包里的隐形依赖。<strong>预期输出基准</strong>：结果表与关键图随包提交，重跑后 diff；允许的浮点差异要预先声明阈值与来源，超阈值即复现失败，而不是「大概一致」。</p>',9)),(e(),B(A,null,{default:E(()=>[o(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20SNAP%5B%22%E6%95%B0%E6%8D%AE%E5%BF%AB%E7%85%A7%20ID%20%E4%B8%8D%E5%8F%AF%E5%8F%98%22%5D%20--%3E%20ENTRY%5B%22%E5%8D%95%E5%91%BD%E4%BB%A4%E5%85%A5%E5%8F%A3%22%5D%0A%20%20TAG%5B%22%E4%BB%A3%E7%A0%81%20tag%22%5D%20--%3E%20ENTRY%0A%20%20ENV%5B%22%E7%8E%AF%E5%A2%83%E9%94%81%20%2B%20%E7%BA%BF%E7%A8%8B%E8%AF%B4%E6%98%8E%22%5D%20--%3E%20ENTRY%0A%20%20ENTRY%20--%3E%20RUN%5B%22%E9%99%8C%E7%94%9F%E4%BA%BA%E6%9C%BA%E5%99%A8%E4%B8%8A%E8%BF%90%E8%A1%8C%22%5D%0A%20%20RUN%20--%3E%20DIFF%7B%22%E4%B8%8E%E5%9F%BA%E5%87%86%20diff%22%7D%0A%20%20DIFF%20--%3E%7C%E9%98%88%E5%80%BC%E5%86%85%7C%20PASS%5B%22%E5%A4%8D%E7%8E%B0%E6%88%90%E7%AB%8B%20%E5%BD%92%E6%A1%A3%22%5D%0A%20%20DIFF%20--%3E%7C%E8%B6%85%E9%98%88%E5%80%BC%7C%20FAIL%5B%22%E5%A4%8D%E7%8E%B0%E5%A4%B1%E8%B4%A5%20%E8%BF%BD%E5%9B%A0%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>标准的判定机制是<strong>陌生人盲跑</strong>：把入口命令、数据引用与文档交给从没碰过这个项目的人，在他不问作者的条件下跑通并对上基准。为什么必须是陌生人：作者自己再跑一遍，会无意识地补上文档没写的隐含步骤——换个目录、先手动下载、跳过某个报错；这些隐含步骤正是包的破绽，只有盲跑能把它们暴露出来。盲跑通过率是复现包唯一的验收指标：一份包要么一次盲跑通过，要么不合格，没有「基本能复现」。</p><p>定案时刻的<strong>双冻结</strong>把包与复盘衔接：代码 tag 与数据快照同刻冻结，案例、结果、包互相引用（<a href="/quant/research-postmortem">研究复盘</a>的同模板归档）。此后数据修正发布，包不受影响——它引用的是旧快照，而旧快照永不可变；要在新数据上重估，那是新版本的事，不是改旧包。<a href="/quant/bf-framework-testing">框架的测试</a>的黄金重放在这里换了个对象：黄金案例从「引擎重放出同一笔成交」变成「包重放出同一张结果表」，验收逻辑同构。</p>',3)),(e(),B(A,null,{default:E(()=>[o(r,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E6%8B%BF%E5%88%B0%E5%A4%8D%E7%8E%B0%E5%8C%85%22%5D%20--%3E%20B%7B%22%E4%BE%9D%E8%B5%96%E5%8F%AF%E5%AE%89%E8%A3%85%EF%BC%9F%22%7D%0A%20%20B%20--%3E%7C%22%E5%90%A6%22%7C%20F1%5B%22%E5%85%B3%E4%B8%80%E5%A4%B1%E8%B4%A5%EF%BC%9A%E7%8E%AF%E5%A2%83%E9%94%81%E7%BC%BA%E5%A4%B1%22%5D%0A%20%20B%20--%3E%7C%22%E6%98%AF%22%7C%20C%7B%22%E8%BE%93%E5%85%A5%E5%90%8C%E4%B8%80%EF%BC%9A%E5%BF%AB%E7%85%A7%20ID%20%E9%92%89%E6%AD%BB%EF%BC%9F%22%7D%0A%20%20C%20--%3E%7C%22%E5%90%A6%22%7C%20F2%5B%22%E5%85%B3%E4%BA%8C%E5%A4%B1%E8%B4%A5%EF%BC%9A%E6%8C%87%E5%90%91%E5%BD%93%E5%89%8D%E7%8A%B6%E6%80%81%20%E9%9D%99%E9%BB%98%E5%8F%98%E6%95%B0%22%5D%0A%20%20C%20--%3E%7C%22%E6%98%AF%22%7C%20D%7B%22%E8%BE%93%E5%87%BA%E4%B8%8E%E5%9F%BA%E5%87%86%20diff%20%E5%9C%A8%E9%98%88%E5%80%BC%E5%86%85%EF%BC%9F%22%7D%0A%20%20D%20--%3E%7C%22%E5%90%A6%22%7C%20F3%5B%22%E5%85%B3%E4%B8%89%E5%A4%B1%E8%B4%A5%EF%BC%9A%E5%BD%92%E7%BA%A6%E9%A1%BA%E5%BA%8F%E6%88%96%E7%BA%BF%E7%A8%8B%E6%95%B0%E6%9C%AA%E5%A3%B0%E6%98%8E%22%5D%0A%20%20D%20--%3E%7C%22%E6%98%AF%22%7C%20G%5B%22%E5%A4%8D%E7%8E%B0%E6%88%90%E7%AB%8B%EF%BC%9A%E8%83%BD%E8%B7%91%E4%B8%94%E8%B7%91%E5%BE%97%E5%90%8C%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<p><span class="marginnote">这张图把问题段的「三关」摊开：上图是五件套怎么组装，这张是验收时逐关卡在哪。直觉类比看陌生人盲跑：像让朋友只按你写的菜谱做菜——你自己下厨时顺手补的那些「少许盐」「看着办」，全都会在朋友那儿变成翻车点；菜谱的破绽，只有交给不认识你的人才测得出来。</span></p><p><span class="marginnote">文档质量有一个粗略的先行指标：出现的「先手动跑一下」「先改一下路径」越多，盲跑通过率越低。每句这种话都是一次把依赖转嫁给读者的记录，写包时看到它们就该变成配置项。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>复现包是<strong>定案的产物，不是探索的日常</strong>：每跑一次就打包会把研究拖死，打包频率跟里程碑走——提案定稿、定案评审、复盘归档各一次。它也不解决正确性：包忠实地复现一个带泄漏的因子，复现得越完美，错误走得越远；正确性由评审清单与预注册判据把关，包只保证「可核查」。最后，包有半衰期：数据供应商改接口、依赖库停维护，几年后旧包可能装不起来；这不是标准失效，是归档的现实——快照与结果表仍能证明当时算出过什么，重跑是另一回事。</p><p><span class="marginnote">常见误区：初学者容易以为复现包是「永久可用的保险箱」。它更像带保质期的罐头：数据供应商改接口、依赖库停止维护，几年后可能装不起来——但罐头里封存的快照与结果表仍然证明「当时算出过什么」；「现在还能跑」从来不是复现标准的承诺，「跑得同」才是。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>「能跑」与「跑得同」是两关：环境锁管可安装，快照 ID 管输入同一，基准 diff 管输出同一。</li><li>五件套：快照引用、代码 tag、环境锁、单命令入口、预期输出基准；手动步骤是隐形依赖。</li><li>唯一验收指标是陌生人盲跑通过；作者自跑不算数，他会无意识补上文档缺的步骤。</li><li>定案时刻双冻结：代码与数据同刻冻结，之后的一切改动都是新版本。</li><li>出处：Sandve et al., <em>PLoS Comput Biol</em>, 2013；站内<a href="/quant/research-postmortem">研究复盘</a>、<a href="/quant/de-data-versioning">数据版本化</a>、<a href="/quant/bf-framework-testing">框架的测试</a>各课。</li></ul>',7))])}const c=s(d,[["render",p]]);export{F as __pageData,c as default};
